		'sw_open_text'        => array( __( 'פתיחה – פסקה גדולה', 'beckwealth' ), 'textarea', 'בעולם הפיננסי התנודתי של ימינו, שבו שווקים גלובליים חווים טלטלות תכופות, מעטים המוסדות השומרים על מעמד יציב ומוניטין חסרי תקדים, כמו המערכת הבנקאית השווייצרית. למרות שינויים ברגולציה הבינלאומית בשורת העשורים האחרונים, ובמיוחד בתחומי המיסוי והשקיפות, שווייץ מנהלת כיום חלק נכבד מהעושר הפרטי הגלובלי המופקד מחוץ למדינות המקור (Offshore Wealth).', 'swiss_page' ),
		'sw_open_q'           => array( __( 'פתיחה – שאלה (זהב)', 'beckwealth' ), 'text', __( 'מה באמת הופך את המדינה האלפינית הקטנה לבירה הפיננסית של העולם, ואילו יתרונות ייחודיים היא מציעה למשקיעים?', 'beckwealth' ), 'swiss_page' ),
