		'sw_hist_text'        => array( __( 'היסטוריה – טקסט', 'beckwealth' ), 'textarea', 'הפיכתה של שווייץ למרכז בנקאי עולמי אינה מקרית, אלא תוצאה של תהליך היסטורי וגיאופוליטי מחושב. אבן הפינה הראשונה הונחה כבר במאה ה-18, כאשר מועצת ז\'נבה חוקקה כללים ראשוניים לשמירה על סודיות פרטי הלקוחות העשירים. אולם, נקודת התפנית המשמעותית התרחשה בראשית המאה ה-20:', 'swiss_page' ),
		'sw_hist_items'       => array( __( 'היסטוריה – פריטים (שנה|כותרת|טקסט)', 'beckwealth' ), 'textarea', "1815|הניטרליות המדינית|המדיניות הניטרלית העקבית של שווייץ, שקובעה בקונגרס וינה (1815) ונשמרה בקפדנות בשתי מלחמות העולם, הפכה אותה ל\"אי של יציבות\" בלב אירופה הסוערת. הון מכל רחבי היבשת זרם לשווייץ כמקלט בטוח מפני החרמות, מלחמות והלאמות.\n1934|חוק הבנקאות של 1934|החוק הפלילי השווייצרי קבע כי הפרת סודיות בנקאית היא עבירה פלילית, שעלולה להוביל למאסר. סעיף זה ביצר את מעמדה של שווייץ ככספת העולמית.", 'swiss_page' ),
