		'sw_adv_items'        => array( __( 'יתרונות – כרטיסים (תג|כותרת|טקסט)', 'beckwealth' ), 'textarea', "AAA|יציבות פוליטית וכלכלית|שווייץ נהנית מאחת המערכות הפוליטיות היציבות בעולם, המבוססת על דמוקרטיה ישירה וחוקה נוקשה. המדינה מחזיקה בדירוג אשראי מושלם (AAA) ובחוב לאומי נמוך. הפרנק השווייצרי (CHF) נחשב לאחד המטבעות החזקים והבטוחים בעולם (\"Safe Haven Currency\"), המגן על הון מפני אינפלציה ושחיקת מטבע.\nPRIVATE BANKING|מומחיות בניהול עושר ודיברסיפיקציה גלובלית|הבנקים השווייצריים מחזיקים במסורת של מאות שנות ניסיון בניהול עושר (Private Banking). הלקוחות נהנים מגישה נרחבת מאד לכל השווקים הבינלאומיים, מגוון רחב של מוצרים פיננסיים מתקדמים, ואפשרויות פיזור נכסים במטבעות ובאזורים גיאוגרפיים שונים.\nFINMA|מסגרת רגולטורית קפדנית והגנה על המפקידים|הרשות המפקחת על השווקים הפיננסיים בשווייץ (FINMA) מציבה סטנדרטים מהמחמירים בעולם לדרישות הון, נזילות וניהול סיכונים. בנוסף, מנגנון ההגנה על פיקדונות בשווייץ מבטיח רמת ביטחון גבוהה במיוחד עבור המשקיעים.\nCRYPTO VALLEY|חדשנות פיננסית ושילוב טכנולוגי|לצד השמירה על המסורת, שווייץ מהווה כיום חלוצה בתחום הפינטק והנכסים הדיגיטליים. אזור \"Crypto Valley\" בעיר צוג (Zug) הדגים כיצד הבנקאות השווייצרית יודעת לשלב בין מערכות פיננסיות מסורתיות לבין טכנולוגיית בלוקצ'יין וניהול נכסים קריפטוגרפיים תחת רגולציה סדורה.", 'swiss_page' ),
		'sw_sum_kicker'       => array( __( 'סיכום – שורה עליונה', 'beckwealth' ), 'text', __( 'לסיכום', 'beckwealth' ), 'swiss_page' ),
		'sw_sum_text'         => array( __( 'סיכום – טקסט', 'beckwealth' ), 'textarea', 'הבנקאות השווייצרית עברה כברת דרך ממעמד של "מקלט מס מוצנע" למעמד של מרכז פיננסי גלובלי מתקדם, שקוף ומתוחכם. השילוב בין יציבות גיאופוליטית, מטבע חזק, רגולציה קפדנית ומסורת של ניהול עושר מותאם אישית, מבטיח כי שווייץ תמשיך להוות יעד מועדף עבור משקיעים ומוסדות המחפשים שמירה על הונם לטווח הארוך.', 'swiss_page' ),
