		'sw_fo_text'          => array( __( 'פמילי אופיס – טקסט', 'beckwealth' ), 'textarea', 'עבור משפחות בעלות הון עתק (UHNW), שווייץ מהווה חממה טבעית. המדינה מציעה אקו-סיסטם פיננסי ומשפטי שאין שני לו, הכולל יועצים ומשפטנים בעלי התמחות ייחודית בהעברת עושר בין-דורי, ניהול סיכונים משפחתי, הקמת נאמנויות (Trusts) ומבני ממשל תאגידי. השילוב של יציבות רגולטורית, מערכת משפטית אמינה ואיכות חיים גבוהה הופך אותה למרכז העולמי המוביל לניהול עושר משפחתי לטווח הארוך.', 'swiss_page' ),
		'sw_faq_title'        => array( __( 'שאלות – כותרת', 'beckwealth' ), 'text', __( 'מה שחשוב לדעת', 'beckwealth' ), 'swiss_page' ),
		'sw_faq_items'        => array( __( 'שאלות (שאלה|תשובה)', 'beckwealth' ), 'textarea', "האם זה חוקי?|לחלוטין. החשבונות נפתחים על שם הלקוח, וכל המבנה בנוי בשקיפות מלאה מול הרגולציה בשתי המדינות.\nאיך ההון מדווח לרשויות בישראל?|החשבונות מדווחים לרשות המסים בישראל במסגרת הסכמי חילופי המידע (CRS). אנחנו עובדים עם מומחי מיסוי בדין הישראלי.\nאיך מגיעים לכסף כשצריך אותו?|הנזילות נשארת שלכם. הוראות משיכה מבוצעות בתוך ימים ספורים, ואפשר להגדיר מראש רמות נזילות שונות לחלקים שונים של התיק.", 'swiss_page' ),

