		'fam_title'           => array( __( 'כותרת (** = זהב)', 'beckwealth' ), 'text', __( 'ניהול הון **אישי ומשפחתי**', 'beckwealth' ), 'svc_fam' ),
		'fam_intro'           => array( __( 'פתיחה (** = מודגש)', 'beckwealth' ), 'textarea', 'כאשר מכלול הנכסים המשפחתיים מתפרס על פני מספר תחומים, מספר מוסדות פיננסיים ומספר מדינות - הניהול השוטף הופך לתובעני מאד ולעיסוק מורכב במיוחד. ללא ראייה כוללת וגורם מקצועי מתכלל, ההון המשפחתי נחשף לכפילויות מס, לשגיאות ניהול ולפספוס הזדמנויות עסקיות. וגם, בתוך המשפחה יכולה להיווצר מתיחות רבה. **ניהול הון מקצועי מעניק לכם אובייקטיביות, שקט נפשי וראייה כוללת וארוכת טווח, שתשמור על האינטרסים של המשפחה.**', 'svc_fam' ),
