		'fam_s2_kicker'       => array( __( 'צומת דרכים – שורה עליונה', 'beckwealth' ), 'text', __( 'צומת דרכים', 'beckwealth' ), 'svc_fam' ),
		'fam_s2_title'        => array( __( 'צומת דרכים – כותרת', 'beckwealth' ), 'text', __( 'כל מה שצריך לדעת על בניית עתיד פיננסי איתן', 'beckwealth' ), 'svc_fam' ),
		'fam_s2_lead'         => array( __( 'צומת דרכים – פסקה ראשית', 'beckwealth' ), 'textarea', 'הגעתם למצב כלכלי מבוסס, וכעת יש לכם הון שצריך לנהל עבור המשפחה, ובהמשך גם להעביר לדורות הבאים. הגעתם לצומת דרכים משמעותי, עם הרבה מאד שיקולים, ולא מעט תקלות בהן אפשר למעוד. ברור שחשוב לכם שההון יסייע למשפחה, ולא יוביל חלילה לפילוג ומריבות. גם חשוב לכם שההון יישמר, יגדל, ולא יתמסמס.', 'svc_fam' ),
		'fam_s2_text'         => array( __( 'צומת דרכים – פסקה שנייה', 'beckwealth' ), 'textarea', 'ניהול הון משפחתי זו מיומנות שונה לחלוטין מהמיומנות שפיתחתם כל השנים במטרה להרוויח את הכסף. כעת נדרשים כלים אחרים, צורת חשיבה אחרת, כדי לקבוע את היעד הפיננסי המשפחתי ולסלול את הדרך להגיע אליו.', 'svc_fam' ),
		'fam_why_kicker'      => array( __( 'הצורך – שורה עליונה', 'beckwealth' ), 'text', __( 'הצורך', 'beckwealth' ), 'svc_fam' ),
