		'fam_why_items'       => array( __( 'הצורך – שלוש פסקאות (שורה לכל אחת)', 'beckwealth' ), 'textarea', "ניהול הון והשקעות זה דבר מורכב. גם משפחה זה דבר מורכב מאד, שדורש הרבה רגישות והבנה. כעת, כאשר מערבים את שתי המורכבויות יחד, ההון והמשפחה, אזי האתגרים גדלים באופן אקספוננציאלי.\nכאשר מכלול הנכסים המשפחתיים מתפרס על פני מספר תחומים, או מספר מוסדות פיננסיים ומדינות, הניהול השוטף הופך לתובעני מאד, צורך זמן ומורכב במיוחד. ללא ראייה כוללת וגורם מתכלל, משפחות רבות נחשפות לכפילויות, לעמדות מס לא יעילות, ולפספוס הזדמנויות עסקיות. וגם, בתוך המשפחה יכולה להיווצר מתיחות רבה.\nבעולם פיננסי מורכב, דינמי וגלובלי, ניהול של הון משפחתי משמעותי דורש הרבה מעבר להשקעה מתוחכמת בשוק ההון. ניהול הון משפחתי הוא תהליך אסטרטגי, מקיף וארוך טווח, שנועד לשמר, להצמיח ולהעביר את העושר המשפחתי מדור לדור בצורה הבטוחה, היעילה והחכמה ביותר.", 'svc_fam' ),
		'fam_why_box_title'   => array( __( 'הצורך – תיבה כהה: כותרת', 'beckwealth' ), 'text', __( 'פתרון ניהול הון מקצועי מעניק לכם אובייקטיביות, שקט נפשי וראייה כוללת וארוכת טווח.', 'beckwealth' ), 'svc_fam' ),
		'fam_why_box_text'    => array( __( 'הצורך – תיבה כהה: טקסט', 'beckwealth' ), 'textarea', 'ניהול מקצועי מאפשר למפות במדוייק ולרכז את כל ההון המשפחתי, ולבנות תכנית עבודה שלוקחת בחשבון את כל המשתנים שיכולים להשפיע. הליווי המקצועי מסתייע בכל אנשי המקצוע הרלוונטיים - רואי חשבון, עורכי דין ומנהלי עיזבונות – תחת ניהול מרכזי אחד, הפועל אך ורק לטובת האינטרסים ארוכי הטווח של המשפחה שלכם, ולפי המטרות שהגדרתם לה.', 'svc_fam' ),
		'fam_inc_kicker'      => array( __( 'מה כולל – שורה עליונה', 'beckwealth' ), 'text', __( 'חמישה תחומי ליבה', 'beckwealth' ), 'svc_fam' ),
		'fam_inc_title'       => array( __( 'מה כולל – כותרת', 'beckwealth' ), 'text', __( 'מה כולל ניהול הון משפחתי?', 'beckwealth' ), 'svc_fam' ),
		'fam_inc_text'        => array( __( 'מה כולל – טקסט', 'beckwealth' ), 'textarea', 'ניהול הון משפחתי נכון, פועל כגורם מתאם ומנהל אינטגרטיבי של כלל נכסי המשפחה. הוא מאחד תחת קורת גג אחת מספר תחומי ליבה:', 'svc_fam' ),
		'fam_pillars'         => array( __( 'תחומי ליבה (כותרת|טקסט)', 'beckwealth' ), 'textarea', "תכנון פיננסי והקצאת נכסים אסטרטגית|בניית תיק נכסים מגוון ומותאם אישית, הכולל השקעות נזילות בשוקי ההון, נדל\"ן בארץ ובחו\"ל - כל זאת בהתאם לפרופיל הסיכון והיעדים המשפחתיים.\nתכנון מס ומבנה משפטי|ייעול מפת המס הבינלאומית והמקומית של המשפחה, הקמת נאמנויות, חברות החזקה ומבנים משפטיים המגנים על הנכסים ומבטיחים עמידה מלאה בדרישות החוק.\nניהול סיכונים והגנה על הנכסים|זיהוי סיכונים כלכליים, משפטיים ורגולטוריים, ובניית מעטפת הגנה שמבטיחה כי ההון המשפחתי ישמור על ערכו גם בתקופות של אי-ודאות גלובלית.\nהכנת דור ההמשך|הקניית ערכים וחינוך פיננסי לדור הצעיר, מתוך שאיפה להכין אותם לקבלת אחריות ולמעורבות הדרגתית בניהול הנכסים והעסק המשפחתי. או לחילופין, לבנות נכסים ומנגנונים שימנעו מהם את הצורך להיות מעורבים, וכך למנוע מראש טעויות כלכליות.\nהעברה בין-דורית ותכנון ירושה|שמירה על ההון בעת המעבר לדור הבא היא מהאתגרים המרכזיים של משפחות אמידות. התהליך כולל ניסוח צוואות, הסכמים בין-דוריים ויצירת מנגנונים למניעת סכסוכים משפחתיים.", 'svc_fam' ),
