		'fam_close_title'     => array( __( 'חזון – כותרת', 'beckwealth' ), 'text', __( 'ניהול הון משפחתי אינו רק ניהול של מספרים ותשואות – הוא ניהול של חזון, ערכים ומורשת.', 'beckwealth' ), 'svc_fam' ),
		'fam_close_text'      => array( __( 'חזון – טקסט', 'beckwealth' ), 'textarea', 'ליווי מקצועי ומותאם אישית יאפשר לכם ליהנות מההון שיצרתם בהווה, תוך הבטחת העתיד הפיננסי של המשפחה, והרווחה של הדורות הבאים.', 'svc_fam' ),
