		'tax_syn_kicker'      => array( __( 'סינרגיה – שורה עליונה', 'beckwealth' ), 'text', __( 'השילוב הסינרגטי', 'beckwealth' ), 'svc_tax' ),
		'tax_syn_lead'        => array( __( 'סינרגיה – פסקה ראשית', 'beckwealth' ), 'textarea', 'ניהול השקעות אינו יכול לפעול במנותק משיקולי מיסוי, אלא חייב ליצור את השילוב הסינרגטי בין אסטרטגיית השקעות חכמה, שכוללת את הצרכים המשפחתיים, יחד עם תכנון מס מוקדם. אחרת, הרבה מאד כספים ילכו לתשלומי מיסים, ובלא שיש לכך הצדקה של ממש.', 'svc_tax' ),
		'tax_syn_text'        => array( __( 'סינרגיה – פסקה שנייה', 'beckwealth' ), 'textarea', 'ופעמים, שעסקאות או השקעות שנראות משתלמות על הנייר, יכולות להתגלות כהפסדיות בגלל תכנון מס לא נכון.', 'svc_tax' ),
		'tax_net_kicker'      => array( __( 'תשואה נטו – שורה עליונה', 'beckwealth' ), 'text', __( 'המדד האמיתי', 'beckwealth' ), 'svc_tax' ),
		'tax_net_title'       => array( __( 'תשואה נטו – כותרת (** = זהב)', 'beckwealth' ), 'text', __( 'תשואה **נטו** ולא תשואה ברוטו', 'beckwealth' ), 'svc_tax' ),
		'tax_net_text'        => array( __( 'תשואה נטו – טקסט', 'beckwealth' ), 'textarea', 'משקיעים רבים נוטים לבחון תיקי השקעות לפי התשואה הגולמית ("ברוטו"). אולם, מה שבאמת משפיע על קצב צמיחת ההון והיקף הנכסים שיישמרו לאורך זמן הוא התשואה הריאלית נטו – לאחר ניכוי דמי ניהול, אינפלציה ומיסוי.', 'svc_tax' ),
		'tax_net_items'       => array( __( 'תשואה נטו – תאים (תג|כותרת|תיאור); האחרון = התוצאה', 'beckwealth' ), 'textarea', "GROSS|ברוטו|התשואה הגולמית\nFEES|דמי ניהול|\nINFLATION|אינפלציה|\nTAX|מיסוי|\nNET|נטו|התשואה הריאלית", 'svc_tax' ),
