		'tax_fit_title'       => array( __( 'התאמה – כותרת', 'beckwealth' ), 'text', __( 'התאמת נכסים לפי צורכי נזילות ומבנה המשפחה', 'beckwealth' ), 'svc_tax' ),
		'tax_fit_lead'        => array( __( 'התאמה – פסקה ראשית', 'beckwealth' ), 'textarea', 'וחשוב להבין - אין "תיק מושלם" שמתאים לכולם. במציאות, לכל משפחה ולכל משקיע יש פרופיל פיננסי ייחודי, סולם ערכים שונה ומטרות אחרות.', 'svc_tax' ),
		'tax_fit_text'        => array( __( 'התאמה – פסקה שנייה', 'beckwealth' ), 'textarea', 'תכנון מבנה האחזקה של הנכסים, תלוי במדינות המוצא של בעלי ההון, וכן במדינות בהן יש בני משפחה ויורשים. לכל מדינה חוקי מס משלה, וצריך לבחור את האחזקה ואת הנכסים, כך שלא להיקלע שלא לצורך לתוך רשת מס צפופה מדי של כל אחת מהמדינות. שיקול נוסף זה מטרות ההון בטווח הקצר, הבינוני והארוך. שילוב של שיקולים אלה יאפשר לבחור את הכלים הנכונים ביותר עבור המשפחה.', 'svc_tax' ),
