		'tax_tiers_kicker'    => array( __( 'רבדים – שורה עליונה', 'beckwealth' ), 'text', __( 'תמהיל נכסים', 'beckwealth' ), 'svc_tax' ),
		'tax_tiers_title'     => array( __( 'רבדים – כותרת', 'beckwealth' ), 'text', __( 'הבסיס לבניית תמהיל נכסים נכון נשען על חלוקה מדורגת לפי צורכי נזילות וטווחי זמן', 'beckwealth' ), 'svc_tax' ),
		'tax_tiers'           => array( __( 'רבדים (טווח|כותרת|טקסט)', 'beckwealth' ), 'textarea', "טווח קצר|רובד הנזילות השוטפת|משאבים המיועדים לקיום השוטף, הוצאות בלתי צפויות או תמיכה בבני משפחה. כאן יושם דגש על מכשירים בעלי נזילות יומיומית, תנודתיות נמוכה והגנה על הקרן.\nטווח בינוני|רובד היעדים הבינוניים|כספים המיועדים להשקעות עסקיות, רכישת נדל\"ן, סיוע לילדים ברכישת דירה או אירועים משפחתיים משמעותיים. ברובד זה ניתן לשלב אג\"ח קונצרניות ומניות בעלות חלוקת דיבידנד יציבה.\nטווח ארוך|רובד העושר הבין-דורי|הון שאינו נדרש למחיה שוטפת ומיועד לצמיחה ארוכת טווח עבור הדורות הבאים. חלק זה מאפשר חשיפה לנכסים בעלי פרמיית אי-נזילות, כגון קרנות השקעה פרטיות (Private Equity), נדל\"ן מניב בינלאומי, תשתיות והשקעות הון סיכון.", 'svc_tax' ),
