		'tax_tiers_text'      => array( __( 'רבדים – סיכום', 'beckwealth' ), 'textarea', 'בניה והתאמה של התמהיל הנכון, מבטיחה כי המשפחה לא תיאלץ לממש נכסים תנודתיים או ארוכי טווח בעיתוי שוק לא מתאים רק בשל צורך תזרימי מיידי.', 'svc_tax' ),
		'tax_leg_kicker'      => array( __( 'העברה בין-דורית – שורה עליונה', 'beckwealth' ), 'text', __( 'שקט נפשי וערכים משותפים', 'beckwealth' ), 'svc_tax' ),
