		'tax_leg_text'        => array( __( 'העברה בין-דורית – טקסט', 'beckwealth' ), 'textarea', 'מעבר לפן הפיננסי היבש, תכנון נכון מונע חיכוך ומחלוקות עתידיות בקרב המשפחה. שילוב של מנגנוני העברה מסודרים (כגון מכתבי כוונות, אמנות משפחתיות והגדרת מוטבים מדויקת) לצד בחירת נכסים פיננסיים מתאימים ותכנון מס, מונע אירועי מס בלתי רצויים בעת העברת הנכסים, ומבטיח כי המעבר ייעשה ברגישות, בשקיפות ובמקצועיות.', 'svc_tax' ),
