		'tax_suit_title'      => array( __( 'חליפה אישית – כותרת', 'beckwealth' ), 'text', __( 'ניהול השקעות אפקטיבי, הוא מלאכת מחשבת של תפירת "חליפה פיננסית אישית".', 'beckwealth' ), 'svc_tax' ),
		'tax_suit_text'       => array( __( 'חליפה אישית – טקסט', 'beckwealth' ), 'textarea', 'על ידי איחוד כוחות בין מנהלי השקעות מנוסים, מומחי מיסוי ויועצים להעברה בין-דורית, שיחדיו, בונים מפת דרכים אסטרטגית פיננסית שמצמיחה את ההון לאורך זמן, ומונעת מראש תשלומי מיסים מיותרים. וכך, מעצימה את מורשת המשפחה לדורות קדימה.', 'svc_tax' ),
