		'trust_what_title'    => array( __( 'הגדרה – כותרת', 'beckwealth' ), 'text', __( 'אז מהי נאמנות?', 'beckwealth' ), 'svc_trust' ),
		'trust_what_text'     => array( __( 'הגדרה – טקסט', 'beckwealth' ), 'textarea', 'נאמנות היא הסדר משפטי שבו יוצר הנאמנות (Settlor) מעביר נכסים (כספים, נדל"ן, מניות או יצירות אמנות) לבעלותו וניהולו של נאמן (Trustee). הנאמן מחויב לפעול אך ורק לטובת המוטבים (Beneficiaries) על פי כתב נאמנות מוגדר מראש.', 'svc_trust' ),
