		'trust_adv_items'     => array( __( 'יתרונות (כותרת|טקסט)', 'beckwealth' ), 'textarea', "הגנה מקיפה על נכסי המשפחה|אחד היתרונות הבולטים בהקמת נאמנות הוא הפרדת הנכסים מנכסיו הפרטיים של יוצר הנאמנות. הפרדה זו מעניקה שכבת הגנה משפטית מפני נושים, תביעות משפטיות, סיכונים עסקיים ואף סכסוכי גירושין עתידיים, ומבטיחה שההון המשפחתי יישאר מוגן.\nתכנון בין-דורי ומניעת סכסוכים|העברת עזבון באמצעות צוואה רגילה, איננו סוף פסוק. אין זה נדיר לראות מאבקים משפטיים ממושכים ויקרים בין יורשים לגבי הצוואה. הנאמנות מאפשרת העברת מקל מתוחכמת, שקטה וחלקה הרבה יותר. באמצעות כתב הנאמנות, ניתן לקבוע מנגנונים מדויקים לחלוקת הכספים – למשל, התנאת קבלת סכומים בגיל מסוים, בסיום לימודים, מימון צרכים רפואיים.\nשמירה על דיסקרטיות ופרטיות|בשונה מצוואות שעוברות הליכים משפטיים פומביים של הוצאת צו ירושה, הסדר נאמנות הוא לרוב פרטי וחסוי. הדבר מאפשר למשפחה לשמור על פרטיות מלאה בנוגע להיקף נכסיה ובאופן חלוקתם.\nיעילות מיסוי ותכנון פיננסי ארוך טווח|הקמת נאמנות מתוכננת היטב מאפשרת לנהל את חבות המס בצורה אופטימלית וחוקית. ניהול נכון של הנאמנות עשוי למנוע כפל מס, לנצל ביעילות פטורים המגיעים בחוק, ולמקסם את התשואה על נכסי המשפחה לאורך זמן.", 'svc_trust' ),
